  slug = excluded.slug, title = excluded.title, category = excluded.category, tags = excluded.tags,
  orientation = excluded.orientation, resolution = excluded.resolution, image_url = excluded.image_url,
  thumbnail_url = excluded.thumbnail_url, dimensions = excluded.dimensions, width = excluded.width,
  height = excluded.height, aspect_ratio = excluded.aspect_ratio, file_size = excluded.file_size,
  format = excluded.format, views = excluded.views, downloads = excluded.downloads,
  uploaded_at = excluded.uploaded_at, added = excluded.added, colors = excluded.colors,
  featured = excluded.featured, trending = excluded.trending;
